  if(value===null||typeof value==='string'||typeof value==='boolean'||typeof value==='number'&&Number.isFinite(value)){emit(JSON.stringify(value));return}
  if(Array.isArray(value)){emit('[');for(let i=0;i<value.length;i++){if(i)emit(',');if(i in value)visit(value[i])}emit(']');return}
  if(value&&typeof value==='object'){emit('{');let first=true;for(const[key,item]of Object.entries(value).sort(([a],[b])=>a<b?-1:a>b?1:0)){if(!first)emit(',');first=false;emit(JSON.stringify(key));emit(':');visit(item)}emit('}');return}
